def decide(observation, tools):
    views = observation['views']
    frame0, frame1 = views[0], views[1]
    heading0, heading1 = frame0['heading'], frame1['heading']
    right_of_end0, right_of_end1 = frame0['right_of_end_m'], frame1['right_of_end_m']

    point0, point1 = tools.point()
    direct_left, direct_right = tools.direct()

    # Prefer point data: if available, use horizontal position and heading sign
    if point0 is not None and point1 is not None:
        frac0, frac1 = point0[0], point1[0]
        if abs(frac0 - frac1) < 0.01:
            # Very similar horizontal position: use heading sign of later frame
            return 1, "right" if heading1 > 0 else "left", {"heading": heading1}
        elif frac0 > frac1:
            return 0, "right" if heading0 > 0 else "left", {"heading": heading0}
        else:
            return 1, "right" if heading1 > 0 else "left", {"heading": heading1}
    elif point0 is not None:
        return 0, "right" if heading0 > 0 else "left", {"heading": heading0}
    elif point1 is not None:
        return 1, "right" if heading1 > 0 else "left", {"heading": heading1}
    else:
        # No point: use direct logits for turn preference
        if direct_right > direct_left:
            return 1, "right", {"heading": heading1}
        else:
            return 0, "left", {"heading": heading0}

